#include <iostream>
using namespace std;

bool hasPrimeDigit(long long x) {
    while (x > 0) {
        int digit = x % 10;
        if (digit == 2 || digit == 3 || digit == 5 || digit == 7)
            return true;
        x /= 10;
    }
    return false;
}

int main() {
    long long x;
    cin >> x;

    if (x % 2 != 0) {
        cout << x / 2 << ' ' << x / 2 + 1;
    } else {
        long long w = x / 2;
        long long w1 = x - w;

        do {
            --w;
            ++w1;
        } while (!hasPrimeDigit(w) || !hasPrimeDigit(w1));

        cout << w << ' ' << w1;
    }

    return 0;
}

#include <iostream>
using namespace std;

int prime(long long x) {
    int count = 0;
    while (x > 0) {
        int digit = x % 10;
        x /= 10;
        if (digit == 2 || digit == 3 || digit == 5 || digit == 7) {
            ++count;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x;
    cin >> x;

    if (x % 2 != 0) {
        cout << x / 2 << ' ' << x / 2 + 1;
    } else {
        long long w = x / 2;
        long long w1 = x - w;

        while (true) {
            --w;
            ++w1;

            if (prime(w) != 0 && prime(w1) != 0) {
                break;
            }
        }

        cout << w << ' ' << w1;
    }

    return 0;
}

